-- ══════════════════════════════════════════════════════════════════
-- FASE 5 · IMPORTACIÓN DEL EXCEL DE CODIFICACIÓN
--
-- Fuente: ARCHIVO PARA CODIFICACIÓN NUEVA ANTONIA.xlsx, hoja FORMATO (175 códigos).
-- Simulacro corrido el 2026-10-08:
--   116 filas ya idénticas · 18 tallas por crear · 7 códigos que cambian de talla
--   · 7 referencias nuevas
--
-- Los 7 cambios de talla son deliberados: los códigos que representaban talla S se
-- reasignan a tallas que sí se venden (Laura, 2026-10-08). No vendemos S.
--   ANT5022 S→4XL · ANT5015 S→2XL · ANT8051 S→3XL · ANT2001 S→2XL
--   ANT6215 S→2XL · ANT8155 S→3XL · ANT8022 M→S
--
-- Se crean también las tres tallas que estaban pendientes de GS1:
--   ANT8062 3XL (jogger) · ANT8164 3XL (short bolsillo) · ANT8081 4XL (conjunto dep.)
--
-- El PVP del Excel manda, y COSTO SIN IVA entra como precio neto Kukos — nunca como
-- costo de producción.
--
-- ANT8022 (TOP DEPORTIVO) se deja FUERA de la importación. El Excel le asigna cuatro
-- códigos y la app solo tiene dos, con el código que el Excel pone en S puesto hoy en M.
-- No se sabe cuál está impreso en las etiquetas de las prendas que quedan, la referencia
-- está descontinuada y son pocas unidades (Laura, 2026-10-08): tocarla solo podría
-- romper lo que hoy funciona. Queda exactamente como está.
--
-- La categoría se deduce de la línea de Kukos, con tres correcciones a mano porque la
-- línea no encajaba: ANT1215 y ANT6201 ('PRENDA EN OFERTA', línea 2016-DEPORTIVOS) van
-- a OFERTAS, y ANT8087 ('CONJUNTO DEPORTIVO CON COPA', línea 2013-CONJUNTOS) va a
-- DEPORTIVO. Si alguna queda mal, se corrige desde el formulario de producto.
-- ══════════════════════════════════════════════════════════════════

BEGIN;

CREATE TEMP TABLE _imp (
  codigo text, base text, talla text, pvp int, kukos int,
  nombre text, dlarga text, dcorta text,
  linea text, genero text, comp text, sil text, uso text, cat text, color text, inv text
) ON COMMIT DROP;


-- ─── 1 · Referencias: crear las nuevas, actualizar las existentes ──
                       precio_neto_kukos, color, marca, desc_larga, desc_corta,
                       k_linea, k_genero, k_componente, k_silueta, k_uso, activo)
SELECT DISTINCT ON (base)
       base, nombre, cat, inv, pvp, kukos, color, 'Antonia Sorev',
       dlarga, dcorta, linea, genero, comp, sil, uso, true
  FROM _imp
 ORDER BY base
ON CONFLICT (referencia_base) DO UPDATE SET
  precio_venta      = EXCLUDED.precio_venta,
  precio_neto_kukos = EXCLUDED.precio_neto_kukos,
  color             = EXCLUDED.color,
  desc_larga        = EXCLUDED.desc_larga,
  desc_corta        = EXCLUDED.desc_corta,
  k_linea           = EXCLUDED.k_linea,
  k_genero          = EXCLUDED.k_genero,
  k_componente      = EXCLUDED.k_componente,
  k_silueta         = EXCLUDED.k_silueta,
  k_uso             = EXCLUDED.k_uso,
  updated_at        = now();

-- ─── 2 · Liberar los códigos que cambian de talla ─────────────────
-- Un código de barras es único en todo el sistema. Antes de moverlo a su talla nueva
-- hay que quitarlo de donde está, o el índice único lo rechaza.
UPDATE productos_variantes v SET codigo_barras = NULL, estado_codigo = 'pendiente_gs1'
  FROM _imp i, productos p
 WHERE v.codigo_barras = i.codigo AND p.referencia_base = i.base
   AND NOT (v.producto_id = p.id AND v.talla = i.talla);

-- ─── 3 · Tallas: crear las que faltan, poner el código en su sitio ─
                                 estado_codigo, activo, precio_venta)
SELECT p.id, i.base || i.talla || '2600', i.talla, i.codigo, 'asignado', true, i.pvp
  FROM _imp i JOIN productos p ON p.referencia_base = i.base
ON CONFLICT (producto_id, talla) DO UPDATE SET
  codigo_barras = EXCLUDED.codigo_barras,
  estado_codigo = 'asignado',
  activo        = true,
  precio_venta  = EXCLUDED.precio_venta;

-- ─── 4 · Las tallas S que quedaron sin código se desactivan ───────
-- No se borran: pueden tener ventas viejas detrás.
UPDATE productos_variantes v SET activo = false
  FROM productos p
 WHERE v.producto_id = p.id AND v.talla = 'S' AND v.codigo_barras IS NULL
   AND p.referencia_base IN (SELECT DISTINCT base FROM _imp);

-- ─── Comprobación ─────────────────────────────────────────────────
SELECT (SELECT count(*) FROM productos)                                        AS productos,
       (SELECT count(*) FROM productos_variantes WHERE activo)                 AS tallas_activas,
       (SELECT count(*) FROM productos_variantes WHERE estado_codigo='asignado') AS con_codigo,
       (SELECT count(*) FROM productos_variantes WHERE estado_codigo='pendiente_gs1' AND activo) AS pendientes,
       (SELECT count(*) FROM productos WHERE precio_neto_kukos IS NOT NULL)    AS con_precio_kukos;

-- Las tres que estaban pendientes, ya con código:
SELECT p.referencia_base, p.nombre, v.talla, v.codigo_barras
  FROM productos p JOIN productos_variantes v ON v.producto_id = p.id
 WHERE (p.referencia_base, v.talla) IN (('ANT8062','3XL'),('ANT8164','3XL'),('ANT8081','4XL'))
 ORDER BY 1;

-- Los 7 códigos que cambiaron de talla:
SELECT v.codigo_barras, p.referencia_base, v.talla
  FROM productos_variantes v JOIN productos p ON p.id = v.producto_id
 WHERE v.codigo_barras IN ('7706730448367','7706730594033','7706730624686','7706730193960',
                           '7706730758824','7706730897516','7706730052359')
 ORDER BY p.referencia_base;
-- Esperado: ANT2001 2XL · ANT5015 2XL · ANT5022 4XL · ANT6215 2XL
--           ANT8022 S · ANT8051 3XL · ANT8155 3XL

COMMIT;
